          <TableHead rowSpan={2}>{t("disc")}</TableHead>
          <TableHead rowSpan={2}>{t("status")}</TableHead>
          <TableHead rowSpan={2}>{t("condition")}</TableHead>
          {extensionFields.map((field) => (
